using System.Reflection;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private static readonly Assembly Domain = typeof(PaymentAuthorization.Domain.Money).Assembly;
    private static readonly Assembly Application = typeof(PaymentAuthorization.Application.AuthorizePayment).Assembly;

    // Technical concerns: I/O, networking, serialization, persistence, processes.
    private static readonly string[] TechnicalAssemblies =
    [
        "System.IO.FileSystem", "System.Net.Http", "System.Net.Http.Json", "System.Net.Sockets",
        "System.Net.Primitives", "System.Text.Json", "System.Data", "System.Data.Common",
        "System.Diagnostics.Process", "System.Private.Uri", "System.Linq.Expressions",
    ];

    private static IEnumerable<string> References(Assembly a) =>
        a.GetReferencedAssemblies().Select(r => r.Name!);

    [Fact]
    public void Domain_depends_on_nothing_but_the_platform()
    {
        var offenders = References(Domain).Where(n => n.StartsWith("PaymentAuthorization")).ToList();
        Assert.True(offenders.Count == 0, $"Domain must not reference: {string.Join(", ", offenders)}");
    }

    [Fact]
    public void Application_depends_only_on_Domain()
    {
        var offenders = References(Application)
            .Where(n => n.StartsWith("PaymentAuthorization") && n != Domain.GetName().Name).ToList();
        Assert.True(offenders.Count == 0, $"Application must not reference: {string.Join(", ", offenders)}");
    }

    [Theory]
    [MemberData(nameof(Inner))]
    public void Business_code_does_not_use_technical_details(string layer, Assembly assembly)
    {
        var offenders = References(assembly)
            .Where(n => TechnicalAssemblies.Contains(n) || n.StartsWith("Microsoft.Extensions.Http")
                || n.StartsWith("Microsoft.EntityFrameworkCore") || n.StartsWith("Microsoft.Data"))
            .ToList();
        Assert.True(offenders.Count == 0, $"{layer} uses technical detail: {string.Join(", ", offenders)}");
    }

    public static TheoryData<string, Assembly> Inner() => new()
    {
        { "Domain", Domain },
        { "Application", Application },
    };
}
